pub(super) fn decode_45(origin: Addr, word: u32) -> R {
    let cands = IV45_BYTE[((word >> 16) & 0xff) as usize];
    match iv_scan(IV45, cands, word) {
        Some((mn, text)) => R::new(mn, text),
        None => undefined(origin, word, "SVE2 top byte 0x45 (unallocated)"),
    }
}

